Here is the commit message:
Fix synchronization in TS3Api

Should fix the issues

Here is the root cause:
The original `exit()` method was declared as a single `synchronized` method that both checked the `connected` flag and performed the actual shutdown work (sending `quit()`, disconnecting the IO layer, shutting down the thread pool) while holding the object's monitor lock. Because `exit()` could be invoked from two different contexts — explicitly by client code and implicitly by `fireDisconnect()`'s asynchronously submitted disconnect-handling task when the connection drops — these two invocations raced on the same lock and on the un-atomic `connected` boolean. If the explicit `exit()` call was blocked inside `api.quit()` (waiting for a server response that itself depends on the IO thread reporting the disconnect and invoking `fireDisconnect()`), the disconnect-handling task attempting to call the same synchronized `exit()` would either have to wait indefinitely (deadlock) or, once unblocked, re-execute the shutdown steps (`io.disconnect()`, `userThreadPool.shutdown()`) a second time, since the original code did not properly guard against concurrent/duplicate shutdown execution. In short, the bug stemmed from conflating "signal that shutdown should happen" with "perform the shutdown," using a coarse-grained synchronized block and a simple volatile flag, which was insufficient to safely coordinate concurrent exit paths.

Here is the patch:
 import java.util.concurrent.ExecutorService;
 import java.util.concurrent.Executors;
+import java.util.concurrent.atomic.AtomicBoolean;

 public class TS3Query {
 	private final TS3Config config;

-	private QueryIO io;
+	private final AtomicBoolean connected = new AtomicBoolean(false);
+	private final AtomicBoolean shuttingDown = new AtomicBoolean(false);

-	private volatile boolean connected;
+	private QueryIO io;

 	/**
 	 */
 	public TS3Query(TS3Config config) {
 		this.config = config;
 		this.fileTransferHelper = new FileTransferHelper(config.getHost());
 		this.connectionHandler = config.getReconnectStrategy().create(config.getConnectionHandler());
-		this.connected = false;

 		this.asyncApi = new TS3ApiAsync(this);
 		this.api = new TS3Api(asyncApi);
 	}


 	public synchronized void connect() {
 		if (userThreadPool.isShutdown()) {
 			throw new IllegalStateException("The query has already been shut down");
 		}

 		QueryIO oldIO = io;
 		if (oldIO != null) {
 			oldIO.disconnect();
 		}

 		io = new QueryIO(this, config);
-		connected = true;
+		connected.set(true);

 		try {
 			connectionHandler.onConnect(this);
 		} catch (Exception e) {
 			log.error("ConnectionHandler threw exception in connect handler", e);
 		}
 		io.continueFrom(oldIO);
 	}

 	 */
-	public synchronized void exit() {
-		if (connected) {
+	public void exit() {
+		if (shuttingDown.compareAndSet(false, true)) {
 			// Sending this command will guarantee that all previously sent commands have been processed
 			try {
 				api.quit();
 			} catch (TS3Exception e) {
 				log.warn("Could not send a quit command to terminate the connection", e);
+			} finally {
+				shutDown();
+			}
+		} else {
+			// Only 1 thread shall ever send quit, the rest of the threads wait for the first thread to finish
+			try {
+				synchronized (this) {
+					while (connected.get()) {
+						wait();
+					}
+				}
+			} catch (InterruptedException e) {
+				// Restore interrupt, then bail out
+				Thread.currentThread().interrupt();
 			}
 		}
+	}

+	private synchronized void shutDown() {
 		if (io != null) {
 			io.disconnect();
 		}

-		connected = false;
 		userThreadPool.shutdown();
+		connected.set(false);
+		notifyAll();
 	}

 	 */
 	public boolean isConnected() {
-		return connected;
+		return connected.get();
 	}


 	void fireDisconnect() {
-		connected = false;
+		connected.set(false);

 		submitUserTask("ConnectionHandler disconnect task", new Runnable() {
 			@Override
 			public void run() {
-				try {
-					connectionHandler.onDisconnect(TS3Query.this);
-				} finally {
-					if (!connected) {
-						exit();
-					}
-				}
+				handleDisconnect();
 			}
 		});
 	}
+
+	private synchronized void handleDisconnect() {
+		try {
+			connectionHandler.onDisconnect(this);
+		} finally {
+			if (!connected.get()) {
+				shutDown();
+			}
+		}
+	}
 }
